// Expected body: { tenant_slug, title, source_type, text } for pasted content,
// or { tenant_slug, title, source_type: 'website', url } for a website fetch.
// PDF is handled client-side (the dashboard form extracts text from the PDF
// in the browser before ever calling this webhook, using the same 'text'
// contract as everything else) -- this workflow never sees a raw PDF file.
const body = $input.first().json.body || {};
for (const f of ['tenant_slug', 'title', 'source_type']) {
  if (!body[f]) throw new Error(`${f} is required`);
}
const validTypes = ['pdf', 'website', 'faq', 'manual_text', 'other'];
if (!validTypes.includes(body.source_type)) {
  throw new Error(`source_type must be one of: ${validTypes.join(', ')}`);
}
if (body.source_type === 'website') {
  if (!body.url) throw new Error('url is required when source_type is website');
  try { new URL(body.url); } catch { throw new Error('url is not a valid URL'); }
} else if (!body.text) {
  throw new Error('text is required');
}
return [{ json: body }];

const tenantRows = $('Resolve Tenant').all();
if (!tenantRows.length) { throw new Error('Unknown or inactive tenant_slug'); }
const input = $('Validate Input').first().json;
return [{ json: { ...input, tenant_id: tenantRows[0].json.tenant_id } }];

// Lightweight, dependency-free HTML-to-text extraction. n8n's Code node
// sandbox has no guaranteed npm access for a real HTML parser (cheerio,
// jsdom), so this is a regex-based strip rather than a proper DOM parse:
// remove script/style blocks and comments, turn block-level tags into line
// breaks, strip all remaining tags, decode a handful of common entities,
// collapse excess whitespace. Good enough for FAQ/policy/about pages.
// KNOWN LIMITATION, not hidden: this will produce empty or garbled output
// on heavily JS-rendered pages (React/Vue SPAs that render client-side) --
// a real fix needs a headless browser, out of scope for a Code node.
const html = String($json.data ?? $json.body ?? '');
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<(br|\/p|\/div|\/li|\/h[1-6]|\/tr)[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/g, "'")
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n\s*\n+/g, '\n\n')
  .trim();

if (!text) {
  throw new Error('No readable text extracted from the URL -- the page may be JS-rendered, blocked this request, or returned no HTML.');
}

return [{ json: { text } }];

// Both the website branch (Extract Website Text) and the pasted-text branch
// (Is Website? false output, still carrying Validate Input's original body)
// converge here into one consistent shape. tenant_id/title/source_type/url
// always come from Merge Tenant specifically -- not from whichever node
// happens to be $json at this point -- same reasoning as every other place
// in this codebase that reads a named upstream node instead of trusting
// $json after a branch: a Postgres RETURNING clause isn't the only thing
// that can leave $json holding the wrong shape, a branch merge can too.
const ctx = $('Merge Tenant').first().json;
return [{ json: {
  tenant_id: ctx.tenant_id,
  title: ctx.title,
  source_type: ctx.source_type,
  source_url: ctx.source_type === 'website' ? ctx.url : null,
  text: $json.text,
}}];

// Simple chunking: split on double-newlines (paragraphs), then merge small
// paragraphs together up to a target size, so chunks aren't too tiny or too huge.
// This is intentionally simple for Phase 3 -- a real implementation would use
// sentence-aware splitting and overlap; flagged as a later improvement, not built now.
const ctx = $('Resolve Content').first().json;
const doc = $('Create Document Row').first().json;
const TARGET_CHARS = 1000;

const paragraphs = ctx.text.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
const chunks = [];
let current = '';
for (const p of paragraphs) {
  if ((current + '\n\n' + p).length > TARGET_CHARS && current) {
    chunks.push(current);
    current = p;
  } else {
    current = current ? current + '\n\n' + p : p;
  }
}
if (current) chunks.push(current);
if (!chunks.length) { throw new Error('No content to chunk -- text was empty after trimming'); }

return chunks.map((content, i) => ({ json: {
  tenant_id: ctx.tenant_id, document_id: doc.document_id, chunk_index: i, content
}}));

const chunk = $('Chunk Text').item.json;
const resp = $json;
const embedding = resp.data && resp.data[0] && resp.data[0].embedding;
if (!embedding) { throw new Error('No embedding returned for chunk ' + chunk.chunk_index); }
return [{ json: { ...chunk, embedding } }];
